<span class="loader" role="status" aria-label="Loading"></span>
<style>.loader{display:inline-block;flex:none;width:10px;height:10px;border:1.5px solid #cdb7b440;border-top-color:var(--accent-color);border-radius:50%;animation:spin 700ms linear infinite}@keyframes spin{to{transform:rotate(360deg)}}</style>
